const observedPasswordAssumptions = "One password occurrence is sampled uniformly from the 32,603,388 occurrences in the pinned RockYou 2009 frequency archive, and exactly one literal guess is made. This historical, service-specific corpus does not estimate current universal account-compromise risk. Online defenses and two-step verification change real attack risk.";
const covidPrevalence = 0.005;
const covidSensitivity = 0.586;
const covidSpecificity = 0.994;
const covidPositivePosterior = covidPrevalence * covidSensitivity / (covidPrevalence * covidSensitivity + (1 - covidPrevalence) * (1 - covidSpecificity));
const covidNegativePosterior = covidPrevalence * (1 - covidSensitivity) / (covidPrevalence * (1 - covidSensitivity) + (1 - covidPrevalence) * covidSpecificity);
const covidPopulation = 100_000;
const covidInfected = Math.round(covidPopulation * covidPrevalence);
const covidUninfected = covidPopulation - covidInfected;
const covidTruePositive = Math.round(covidInfected * covidSensitivity);
const covidFalseNegative = covidInfected - covidTruePositive;
const covidFalsePositive = Math.round(covidUninfected * (1 - covidSpecificity));
const covidTrueNegative = covidUninfected - covidFalsePositive;
const covidDiagnosticModel: BinaryTestModel = {
  population: covidPopulation,
  prevalence: covidPrevalence,
  sensitivity: covidSensitivity,
  specificity: covidSpecificity,
  infected: covidInfected,
  uninfected: covidUninfected,
  truePositive: covidTruePositive,
  falsePositive: covidFalsePositive,
  falseNegative: covidFalseNegative,
  trueNegative: covidTrueNegative,
  positiveTotal: covidTruePositive + covidFalsePositive,
  negativeTotal: covidFalseNegative + covidTrueNegative,
  positiveLikelihoodRatio: covidSensitivity / (1 - covidSpecificity),
  negativeLikelihoodRatio: (1 - covidSensitivity) / covidSpecificity,
  positiveShift: decibans(lower(covidPositivePosterior)) - decibans(lower(covidPrevalence)),
  negativeShift: decibans(lower(covidNegativePosterior)) - decibans(lower(covidPrevalence)),
};
const gbCarInjuryCollisionRatePerKm = 484 / (1_000_000_000 * 1.609344);
const injuryCollisionOver = (kilometres: number): number => -Math.expm1(-gbCarInjuryCollisionRatePerKm * kilometres);
const gbCarInjuryCollision20Km = injuryCollisionOver(20);
const gbCarInjuryCollision500Km = injuryCollisionOver(500);
const rouletteBet = (id: string, title: string, shortTitle: string, description: string, winningPockets: number, netPayoutMultiplier: number, color: string, halfZero = false): Landmark => {
  const stake = 100;
  const netPayout = stake * netPayoutMultiplier;
  const expectedReturn = halfZero ? "−€100/74 ≈ −€1.35 per €100 bet" : "−€100/37 ≈ −€2.70 per €100 bet";
  const zeroRule = halfZero
    ? "If zero wins, the casino returns half the €100 stake, so the net loss is €50."
    : "An uncovered number loses the €100 stake.";
  const returnedStake = winningPockets === 24
    ? "returns the €50 placed on the winning dozen or column"
    : "returns the €100 stake";
  const calculation = halfZero
    ? "p = 18/37; expected net return = [(18 × €100) − (18 × €100) − €50] / 37 = −€100/74 ≈ −€1.35 per €100"
    : `p = ${winningPockets}/37; expected net return = [(${winningPockets} × €${netPayout}) − (${37 - winningPockets} × €100)] / 37 = −€100/37 ≈ −€2.70 per €100`;
  return {
    id,
    title,
    shortTitle,
    chance: lowerRatio(winningPockets, 37),
    size: 88,
    art: rouletteArtwork(winningPockets, color),
    explanation: `${description} On a €100 stake, a win adds €${netPayout} net and ${returnedStake}. ${zeroRule} Over many spins, the average net return is ${expectedReturn}.`,
    calculation,
    assumptions: "This exact model uses a €100 stake on a fair 37-pocket single-zero wheel under French roulette anglaise rules. Its expected return is an average over repeated plays.",
    sources: [rouletteRulesSource, rouletteOperatorSource],
    classification: exact,
  };
};

